<?php require_once __DIR__ . '/core/bootstrap.php'; require_login(); $u = current_user(); $where = "target_type = 'global'"; if (($u['role'] ?? '') === 'padre') { $st_ids = array_column((new StudentModel())->children_of($u['id']), 'id'); $course_ids = array_column((new StudentModel())->children_of($u['id']), 'course_id'); if (!empty($st_ids)) { $in_st = implode(',', $st_ids); $in_c = implode(',', $course_ids); $where = "(target_type = 'global' OR (target_type = 'course' AND course_id IN ($in_c)) OR (target_type = 'student' AND student_id IN ($in_st)))"; } } elseif (($u['role'] ?? '') === 'estudiante') { $st = (new StudentModel())->by_user($u['id']); if ($st) $where = "(target_type = 'global' OR (target_type = 'course' AND course_id = {$st['course_id']}) OR (target_type = 'student' AND student_id = {$st['id']}))"; } $ann = db()->query("SELECT a.*, u.full_name AS author FROM announcements a LEFT JOIN users u ON u.id = a.created_by WHERE $where ORDER BY a.created_at DESC")->fetchAll(); $page_title = t('comunicados'); require __DIR__ . '/views/layout_header.php'; ?>
<section class="card animate-in"><h2 class="metal-text"><?= e(t('comunicados')) ?></h2><div class="cards"><?php foreach ($ann as $a): ?><article class="card reveal"><h3><?= e($a['title']) ?></h3><p><?= nl2br(e($a['content'])) ?></p><div style="margin-top:12px;font-size:.85rem;color:var(--muted)"><span class="badge"><?= e($a['target_type']) ?></span> · Por: <?= e($a['author'] ?? 'Admin') ?> · <?= e($a['created_at']) ?></div></article><?php endforeach; ?><?php if (empty($ann)): ?><p>No hay comunicados disponibles.</p><?php endif; ?></div></section><?php require __DIR__ . '/views/layout_footer.php'; ?>
